entries[376492] = { ["name"] = "Hood of Surging Time", ["text"] = "5 sec cast 3\nReagents:\nAiry Soul , Chronocloth Bolt (4), Temporal Spellthread , Spark (#247)\nOptional Reagents:\nZone:\nAlgeth'ar Academy & Uldaman: Legacy of Tyr\nRecipe:\nPurchasable on the Auction House\n\nHood of Surging Time\nBinds when picked up\nHead Cloth\n164 Armor\n+257 Intellect\n+416 Stamina\n+ 243 Haste\n+ 236 Versatility\nDurability 100 / 100\nEquip: Damaging a new enemy grants you 119 Haste for 10 sec, up to 5 stacks.\n70" }
