entries[376494] = { ["name"] = "Infurious Binding of Gesticulation", ["text"] = "5 sec cast 3\nReagents:\nTallstrider Sinew (2), Infurious Wildercloth Bolt (16), Azureweave Bolt , Vibrant Spellthread , Spark (#247)\nOptional Reagents:\nVendor:\nEraneth\nZone:\nValdrakken\nCost:\n3\n\nInfurious Binding of Gesticulation\nBinds when picked up\nWaist Cloth\n123 Armor\n+193 Intellect\n+312 Stamina\n+ 231 Versatility\n+ 128 Mastery\nDurability 55 / 55\nEquip: Successfully applying a loss of control effect to an enemy, interrupting an enemy, or dispelling any target increases your primary stat by 200 for 10 sec. May occur once every 30 sec.\n70" }
entries[376495] = { ["name"] = "Infurious Legwraps of Possibility", ["text"] = "5 sec cast 3\nReagents:\nInfurious Wildercloth Bolt (20), Chronocloth Bolt , Vibrant Spellthread , Spark (#247)\nOptional Reagents:\nVendor:\nEraneth\nZone:\nValdrakken\nCost:\n3\n\nInfurious Legwraps of Possibility\nBinds when picked up\nLegs Cloth\n191 Armor\n+257 Intellect\n+416 Stamina\n+ 143 Haste\n+ 335 Versatility\nDurability 120 / 120\nEquip: After recovering from a loss of control effect, you become empowered with possibility, increasing your Haste by 395 for 10 sec. This effect may only occur once every 30 sec.\n70" }
