entries[376531] = { ["name"] = "Explorer's Banner of Herbology", ["text"] = "3.5 sec cast\nReagents:\nOmnium Draconis (12), Spool of Wilderthread (2), Vibrant Wildercloth Bolt (7)\nOptional Reagents:\nEmbroidery Thread (#181) , Illustrious Insight (#93)\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 15\nCost:\n750\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 15\nCost:\n750\n\nExplorer's Banner of Herbology\nBinds when used\n\nUse: Place a banner that increases damage done to all Air and Frost Elementals within 100 yards by 50%. Also grants 18 Deftness and Finesse to Herbalists. Lasts 10 min. Only usable in the Dragon Isles. (10 Min Cooldown)\nRequires Dragon Isles Herbalism\n(1)" }
entries[376532] = { ["name"] = "Explorer's Banner of Geology", ["text"] = "3.5 sec cast\nReagents:\nSpool of Wilderthread (2), Elemental Harmony (2), Wildercloth Bolt (2)\nOptional Reagents:\nEmbroidery Thread (#181) , Illustrious Insight (#93)\nVendor:\nBoss Magor\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 15\nCost:\n750\n\nVendor:\nCataloger Jakes\nZone:\nThe Waking Shores\nDragonscale Expedition - Renown 15\nCost:\n750\n\nExplorer's Banner of Geology\nBinds when used\n\nUse: Place a banner that increases damage done to all Earth and Fire Elementals within 100 yards by 50%. Also grants 18 Deftness and Finesse to Miners. Lasts 10 min. Only usable in the Dragon Isles. (10 Min Cooldown)\nRequires Dragon Isles Mining\n(1)" }
