entries[376537] = { ["name"] = "Shimmering Embroidery Thread", ["text"] = "1.5 sec cast\nReagents:\nSpool of Wilderthread , Silken Gemdust\nOptional Reagents:\nLesser Illustrious Insight (#92)\nDrop:\nWorld Creatures\nArea:\nThe Dragon Isles\nRecipe:\nPurchasable on the Auction House\n\nShimmering Embroidery Thread\nFinishing Crafting Reagent\n\nWhen crafting: Increases reagents saved from Resourcefulness by 25%.\nUsable with: Most Dragon Isles Tailoring Embroidery and Garment Recipes." }
